function showTip(e,h){tip.innerHTML=h;tip.style.opacity=1;tip.style.left=Math.min(e.clientX+14,innerWidth-310)+'px';tip.style.top=(e.clientY+14)+'px'}
const hideTip=()=>tip.style.opacity=0;
function hbars(el,pairs,max){const m=max||Math.max(...pairs.map(p=>p[1]),1);el.innerHTML=pairs.map(p=>`<div class="hrow"><span title="${p[2]||p[0]}" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${p[0]}</span><div class="track"><div class="fill" style="width:${(100*p[1]/m).toFixed(1)}%;background:var(${p[3]||'--series-1'})"></div></div><span style="text-align:right;font-variant-numeric:tabular-nums">${p[4]||p[1]}</span></div>`).join('')}
