 const jo={};L.forEach(x=>jo[x.g]=(jo[x.g]||0)+1);hbars(document.getElementById('ljbars'),Object.entries(jo).sort((a,b)=>b[1]-a[1]).map(([k,n])=>[DATA.gname[k]||k,n,k,'--series-3']));
 document.getElementById('lcount').textContent=`(${L.length})`;const ord={settled:0,decided:1,appeal:2,ongoing:3,filed:4,dismissed:5,withdrawn:6};
